//! Chechen inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Chechen dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Case {
    Nominative,
    Genitive,
    Dative,
    Ergative,
    Allative,
    Instrumental,
    Lative,
    Comparative,
}

impl Case {
    pub const ALL: [Self; 8] = [Self::Nominative, Self::Genitive, Self::Dative, Self::Ergative, Self::Allative, Self::Instrumental, Self::Lative, Self::Comparative];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Class {
    JJ,
    DD,
    BD,
    VB,
    BB,
    JB,
    J,
    D,
    B,
    V,
}

impl Class {
    pub const ALL: [Self; 10] = [Self::JJ, Self::DD, Self::BD, Self::VB, Self::BB, Self::JB, Self::J, Self::D, Self::B, Self::V];
}

/// Settings for systematic choices. `Chechen::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Chechen {
    pub options: Options,
}

impl Chechen {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Genitive, Number::Singular,) => Some(2),
            (Case::Genitive, Number::Plural,) => Some(3),
            (Case::Dative, Number::Singular,) => Some(4),
            (Case::Dative, Number::Plural,) => Some(5),
            (Case::Ergative, Number::Singular,) => Some(6),
            (Case::Ergative, Number::Plural,) => Some(7),
            (Case::Allative, Number::Singular,) => Some(8),
            (Case::Allative, Number::Plural,) => Some(9),
            (Case::Instrumental, Number::Singular,) => Some(10),
            (Case::Instrumental, Number::Plural,) => Some(11),
            (Case::Lative, Number::Singular,) => Some(12),
            (Case::Lative, Number::Plural,) => Some(13),
            (Case::Comparative, Number::Singular,) => Some(14),
            (Case::Comparative, Number::Plural,) => Some(15),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_scored(word, case, number), word)
    }

    /// Scored class of a noun.
    pub fn noun_class(&self, word: &str) -> Scored<Class> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Class::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A num form.
    pub fn num_scored(&self, word: &str, case: Case) -> Scored<String> {
        let cell: Option<u32> = match (case,) {
            (Case::Nominative,) => Some(0),
            (Case::Genitive,) => Some(1),
            (Case::Dative,) => Some(2),
            (Case::Ergative,) => Some(3),
            (Case::Allative,) => Some(4),
            (Case::Instrumental,) => Some(5),
            (Case::Lative,) => Some(6),
            (Case::Comparative,) => Some(7),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A num form. The best candidate; the word itself if nothing is known.
    pub fn num(&self, word: &str, case: Case) -> String {
        best(self.num_scored(word, case), word)
    }

    /// Dictionary spelling of a num (with stress marks where the data has them).
    pub fn num_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

}

/// A noun form.
pub fn noun(word: &str, case: Case, number: Number) -> String {
    Chechen::default().noun(word, case, number)
}

/// A noun form. Every candidate with its confidence, best first.
pub fn noun_scored(word: &str, case: Case, number: Number) -> Scored<String> {
    Chechen::default().noun_scored(word, case, number)
}

/// Scored class of a noun.
pub fn noun_class(word: &str) -> Scored<Class> {
    Chechen::default().noun_class(word)
}

/// Dictionary spelling of a noun.
pub fn noun_lemma(word: &str) -> String {
    Chechen::default().noun_lemma(word)
}

/// A num form.
pub fn num(word: &str, case: Case) -> String {
    Chechen::default().num(word, case)
}

/// A num form. Every candidate with its confidence, best first.
pub fn num_scored(word: &str, case: Case) -> Scored<String> {
    Chechen::default().num_scored(word, case)
}

/// Dictionary spelling of a num.
pub fn num_lemma(word: &str) -> String {
    Chechen::default().num_lemma(word)
}

/// One reading of a form: its part of speech, lemma, and every cell it fills
/// for that lemma (empty when it is only the dictionary form).
#[derive(Clone, Debug, PartialEq)]
pub struct Analysis {
    pub pos: &'static str,
    pub lemma: String,
    pub cells: Vec<&'static str>,
}

/// Which lemma and cell a form could be, best first. Works for unknown words too.
pub fn analyze(word: &str) -> Scored<Analysis> {
    let Some(m) = model() else { return Vec::new() };
    m.analyze(word)
        .into_iter()
        .filter_map(|(a, p)| {
            let pos = m.pos.get(a.pos)?;
            let cells = a.cells.iter().filter_map(|&c| pos.cells.get(c as usize).map(String::as_str)).collect();
            Some((Analysis { pos: pos.name.as_str(), lemma: a.lemma, cells }, p))
        })
        .collect()
}

/// Inflect by names, e.g. `inflect("noun", "GenitivePlural", word)`.
pub fn inflect(pos: &str, cell: &str, word: &str) -> Scored<String> {
    let Some(m) = model() else { return Vec::new() };
    let Some(pi) = m.pos.iter().position(|p| p.name == pos) else { return Vec::new() };
    let Some(ci) = m.pos.get(pi).and_then(|p| p.cells.iter().position(|c| c == cell)) else { return Vec::new() };
    m.inflect(pi, ci as u32, word, Options::default())
}
